pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address from = address(0x123);
        address caddress = address(0x456);
        address[] memory tos = new address[](1);
        tos[0] = address(0x789);
        uint v = 0;
        // Deploy a mock at caddress that always reverts on transferFrom
        vm.etch(caddress, address(new RevertingMock()).code);
        bool ok;
        try c.transfer(from, caddress, tos, v) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok, "Test failed: reference should revert");
    }
}

contract RevertingMock {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        revert("always revert");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address from = address(0x123);
        address caddress = address(0x456);
        address[] memory tos = new address[](1);
        tos[0] = address(0x789);
        uint256 value = 100;

        // Make caddress's transferFrom revert by not giving it any code
        // The call will fail, causing revert in reference but bug skips loop
        vm.prank(from);
        bool ok;
        try c.transfer(from, caddress, tos, value) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

