    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address from = address(0x1);
        address caddress = address(0x2);
        address[] memory tos = new address[](1);
        tos[0] = address(0x3);
        uint v = 0;
        vm.prank(from);
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.transfer.selector, from, caddress, tos, v));
        assertTrue(ok == false);
    }
}

